// The issue landscape is drawn per seed for synthetic voters only: never from venue, party or real data.
function landscape(seed){const order=[...POLICY_TOPICS].sort((a,b)=>rand(seed,'heat-order',a)-rand(seed,'heat-order',b)),weights={},lean={};order.forEach((t,i)=>{weights[t]=(i===0?3:i===1&&rand(seed,'second-hot')<.6?2:1)*(.8+rand(seed,'heat',t)*.4);lean[t]=[.3,.4,.6,.7][Math.floor(rand(seed,'lean',t)*4)];});const later=order.slice(1);return{weights,lean,surge:{topic:later[Math.floor(rand(seed,'surge-topic')*later.length)],round:4+Math.floor(rand(seed,'surge-round')*4),length:2}};}
function voterCares(seed,i,weights){const pick=(salt,skip)=>{let r=rand(seed,salt,i)*POLICY_TOPICS.reduce((n,t)=>n+(t===skip?0:weights[t]),0);for(const t of POLICY_TOPICS){if(t===skip)continue;r-=weights[t];if(r<0)return t;}return POLICY_TOPICS.filter(t=>t!==skip).at(-1);},first=pick('care-1');return rand(seed,'care-two',i)<.5?[first,pick('care-2',first)]:[first];}
const prefers=(v,topic)=>{const k=POLICY_TOPICS.indexOf(topic);return k<0?-1:Number(v.pref?.[k]??0);};
function surgeActive(s,topic,day=s.day){const g=s.landscape?.surge;return!!g&&g.topic===topic&&day>=g.round&&day<g.round+g.length;}
function caresAbout(s,v,i,topic,day=s.day){return(v.cares||[]).includes(topic)||surgeActive(s,topic,day)&&rand(s.seed,'surge-care',i)<TUNING.surgeShare;}
