const WELFARE=[{title:'照護者的喘息申請',npc:'許晴',request:'家人照護讓我分不開身。我想知道可申請哪些喘息協助，你能保證一定核准嗎？',guarantee:'我保證下個月一定核准你的照護補助，全額到位'},{title:'租屋急難的申請困難',npc:'阿祺',request:'這個月遇到急難，申請資料又看不懂。你能幫我整理流程，還是保證直接拿到租屋補助？',guarantee:'我保證下個月一定核准你的租屋補助，全額到位'},{title:'無障礙接送的資格詢問',npc:'佳穎',request:'我想查無障礙接送的申請條件。你會先幫我查資格，還是保證每次都能安排？',guarantee:'我保證下個月你的接送申請全部核准，每次都有車'}];
function tipEvidence(t){if(t.verification)return'後續核對回覆：'+t.verification.text;if(!t.evidenceLevel)return'只有匿名片段，日期與原始附件尚未核對；目前不能確認指控。';const texts={issue:['兩份摘要出現相同案號與金額，但仍缺原始請款附件，尚不能定論。','本局原始附件確認有重複請款，已列為待正式處理的帳目問題；是否涉及犯罪仍不能自行定罪。'],false:['來信截圖與帳目日期不一致，可能是不同版本或年度，需要核對原件。','核對後發現是不同年度的同名活動，原來的重複請款指控不成立。'],unclear:['部分金額對不上，但關鍵附件缺失；只能說有待核對，不能定論。','已查到可取得的資料，關鍵附件仍缺失，無法證實或排除帳目問題。']};return texts[t.truth][Math.min(t.evidenceLevel,2)-1];}
function eventView(s){upgrade(s);const t=s.events.tip,w=WELFARE[s.events.welfare.variant];return{tip:{available:s.day>=3,title:TOPICS.tip.title,summary:'匿名資料指稱虛構「青榕活動案」可能重複請款。這不是任何真實人物或政黨的指控。',evidenceLevel:t.evidenceLevel,evidenceText:tipEvidence(t),investigationCost:30000,investigations:t.investigations,maxInvestigations:2,canInvestigate:t.evidenceLevel<2&&!t.verification,history:t.history.map(x=>({round:x.round,stage:x.stage,mode:x.mode,quote:x.quote,evidenceLevel:x.evidenceLevel,evidenceText:x.evidenceText})),publication:t.publication?copy(t.publication):null,update:t.verification?copy(t.verification):null,responseDue:t.responseDue,truthLabel:t.evidenceLevel===2||t.verification?({issue:'確認帳目問題，未認定犯罪',false:'原線索不成立',unclear:'仍無法釐清'})[t.truth]:null},welfare:{available:s.day>=2,title:w.title,request:w.request,npc:w.npc,status:s.events.welfare.reply?.status||'尚未接觸',reply:copy(s.events.welfare.reply||null),promise:copy(s.player.promises.find(p=>p.topic==='welfare')||null)}};}
function availableTopics(s){return Object.values(TOPICS).filter(t=>t.id!=='welfare'&&t.id!=='tip'||t.id==='welfare'&&s.day>=2||t.id==='tip'&&s.day>=3);}
function guaranteeText(s,topic){if(topic==='sanitation')return'我保證下個月全市鼠患全部解決';if(topic==='senior')return'我保證下個月敬老卡點數加倍，大家都能用';return topic==='access'?'我保證下個月改善完成，大家都不受影響':topic==='welfare'?WELFARE[s.events.welfare.variant].guarantee:'我保證下個月路口改好，通行問題一次解決';}
